const configuredApiBase = (process.env.NEXT_PUBLIC_API_BASE_URL || "").trim().replace(/\/$/, "");
const API_ORIGIN = configuredApiBase
  ? configuredApiBase.replace(/\/api$/, "")
  : "http://localhost:3001";

const FALLBACK_IMAGE =
  "data:image/svg+xml;base64,";

export function resolveImageUrl(value) {
  if (!value || typeof value !== "string") {
    return FALLBACK_IMAGE;
  }

  const src = value.trim();
  if (!src) {
    return FALLBACK_IMAGE;
  }

  if (/^(https?:|data:|blob:)/i.test(src)) {
    return src;
  }

  if (src.startsWith("//")) {
    return `${window.location.protocol}${src}`;
  }

  if (src.startsWith("/")) {
    return `${API_ORIGIN}${src}`;
  }

  return `${API_ORIGIN}/${src}`;
}

export function resolveImageList(images, fallbackImage) {
  if (Array.isArray(images) && images.length > 0) {
    return images.map((item) => resolveImageUrl(item));
  }
  if (fallbackImage) {
    return [resolveImageUrl(fallbackImage)];
  }
  return [FALLBACK_IMAGE];
}

